function formula(value,refs={}){if(value===undefined||value===null||value==='')return 0;let s=String(value).replace(/@[\w.]+/g,key=>{if(!(key in refs))throw Error('Не поддержана формула '+value);return refs[key]});if(!/^[\d\s.+*/()\-]+$/.test(s))throw Error('Не поддержана формула '+value);const tokens=s.match(/\d*\.?\d+|[()+*/\-]/g)||[];let p=0;function primary(){let t=tokens[p++];if(t==='-')return -primary();if(t==='+')return primary();if(t==='('){let n=sum();if(tokens[p++]!==')')throw Error('Формула');return n}let n=Number(t);if(!Number.isFinite(n))throw Error('Формула');return n}function product(){let n=primary();while(['*','/'].includes(tokens[p])){let op=tokens[p++],b=primary();n=op==='*'?n*b:n/b}return n}function sum(){let n=product();while(['+','-'].includes(tokens[p])){let op=tokens[p++],b=product();n=op==='+'?n+b:n-b}return n}const n=sum();if(p!==tokens.length||!Number.isFinite(n))throw Error('Формула');return n}
